const evt = $json;
const execution = evt.execution || {};
const err = execution.error || evt.error || {};
const nodeName = execution.lastNodeExecuted || 'Unknown';
const msg = (err.message || '').toString();

let errorType = 'unknown';
if (/timeout|ETIMEDOUT|ECONNRESET/i.test(msg)) errorType = 'network_timeout';
else if (/401|403|unauthor|forbidden|invalid.*token|api.*key/i.test(msg)) errorType = 'auth_failure';
else if (/429|rate.?limit/i.test(msg)) errorType = 'rate_limit';
else if (/400|invalid|missing|required|validation/i.test(msg)) errorType = 'data_validation';
else if (/500|502|503|504|gateway/i.test(msg)) errorType = 'upstream_5xx';
else if (/supabase|database|connection/i.test(msg)) errorType = 'database';

return { json: {
  errorDetails: {
    message: msg,
    node: { name: nodeName },
    data: err.context || err.data || {},
    stack: (err.stack || '').toString().substring(0, 2000)
  },
  errorType,
  detectedAt: new Date().toISOString(),
  executionId: (execution.id || '').toString()
} };

const orig = $node['Classify Error Type'].json;
let diag;
try { diag = JSON.parse($json.choices[0].message.content); }
catch (e) { diag = { diagnosis: 'LLM diagnosis parse failed', rootCause: orig.errorType, suggestedFix: 'manual review', severity: 'high', canAutoRecover: false, recoveryStrategy: 'slack_escalation' }; }
const allowed = ['wait_retry','auto_correct','fallback_email','slack_escalation'];
if (!allowed.includes(diag.recoveryStrategy)) diag.recoveryStrategy = 'slack_escalation';
return { json: {
  error: orig.errorDetails,
  errorType: orig.errorType,
  recoveryStrategy: diag.recoveryStrategy,
  retryDelay: diag.recoveryStrategy === 'wait_retry' ? 60000 : 0,
  detectedAt: orig.detectedAt,
  executionId: orig.executionId,
  llmDiagnosis: diag
} };

const payload = $json;
const data = (payload.error && payload.error.data) || {};
const corrected = Object.assign({}, data);
const notes = [];
if (corrected.email && typeof corrected.email === 'string') {
  const before = corrected.email;
  corrected.email = corrected.email.trim().toLowerCase();
  if (before !== corrected.email) notes.push('normalized email');
}
if (corrected.phone && typeof corrected.phone === 'string') {
  let digits = corrected.phone.replace(/\D/g, '');
  if (digits.length === 10) digits = '1' + digits;
  const newPhone = digits ? '+' + digits : '';
  if (newPhone !== corrected.phone) { corrected.phone = newPhone; notes.push('normalized phone'); }
}
if (!corrected.lastName) { corrected.lastName = 'Unknown'; notes.push('defaulted lastName'); }
if (!corrected.company) { corrected.company = 'Unknown'; notes.push('defaulted company'); }
if (corrected.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(corrected.email)) notes.push('email still invalid');
return { json: Object.assign({}, payload, { correctedData: corrected, correctionApplied: true, correctionNotes: notes, correctedAt: new Date().toISOString() }) };
